'use client';

import { useState } from 'react';

export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen gap-6">
      <h1 className="text-4xl font-bold">Contador</h1>

      <div className="flex items-center gap-4">
        <button
          onClick={() => setCount(count - 1)}
          className="px-6 py-2 bg-red-500 text-white font-bold rounded-lg hover:bg-red-600 transition"
        >
          -
        </button>

        <span className="text-6xl font-bold">{count}</span>

        <button
          onClick={() => setCount(count + 1)}
          className="px-6 py-2 bg-green-500 text-white font-bold rounded-lg hover:bg-green-600 transition"
        >
          +
        </button>
      </div>

      <p className="text-xl">El doble es {count * 2}</p>

      {count > 5 && <p className="text-2xl text-orange-500 font-bold">¡Más de 5!</p>}
    </div>
  );
}

