'use client';

interface Product {
  id: number;
  name: string;
  price: number;
}

interface ShoppingCartProps {
  cart: Map<number, number>;
  products: Product[];
  onUpdateQuantity: (productId: number, quantity: number) => void;
}

export default function ShoppingCart({
  cart,
  products,
  onUpdateQuantity,
}: ShoppingCartProps) {
  const productMap = new Map(products.map((p) => [p.id, p]));

  const total = Array.from(cart.entries()).reduce((sum, [productId, quantity]) => {
    const product = productMap.get(productId);
    return sum + (product ? product.price * quantity : 0);
  }, 0);

  return (
    <div className="bg-white rounded-lg shadow-md p-6 sticky top-8">
      <h2 className="text-2xl font-bold text-gray-900 mb-6">Carrito</h2>
      {cart.size === 0 ? (
        <p className="text-gray-600 text-center py-8">El carrito está vacío</p>
      ) : (
        <>
          <div className="space-y-4 mb-6">
            {Array.from(cart.entries()).map(([productId, quantity]) => {
              const product = productMap.get(productId);
              return (
                <div
                  key={productId}
                  className="border border-gray-200 rounded-lg p-4"
                >
                  <h3 className="font-semibold text-gray-900 mb-2">
                    {product?.name}
                  </h3>
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-gray-600">
                      ${product?.price.toFixed(2)}
                    </p>
                    <p className="font-semibold text-gray-900">
                      ${((product?.price || 0) * quantity).toFixed(2)}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() =>
                        onUpdateQuantity(productId, quantity - 1)
                      }
                      className="bg-red-500 hover:bg-red-600 text-white font-bold py-1 px-3 rounded transition"
                    >
                      −
                    </button>
                    <span className="px-4 font-semibold text-gray-900">
                      {quantity}
                    </span>
                    <button
                      onClick={() =>
                        onUpdateQuantity(productId, quantity + 1)
                      }
                      className="bg-green-500 hover:bg-green-600 text-white font-bold py-1 px-3 rounded transition"
                    >
                      +
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
          <div className="border-t border-gray-200 pt-4">
            <div className="flex items-center justify-between">
              <span className="text-lg font-bold text-gray-900">Total:</span>
              <span className="text-2xl font-bold text-blue-600">
                ${total.toFixed(2)}
              </span>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

