  nombre: string;
  email: string;
}

interface Database {
  users: User[];
}

declare global {
  var db: Database | undefined;
}

function initializeDb(): Database {
  if (!globalThis.db) {
    globalThis.db = {
      users: [],
    };
  }
  return globalThis.db;
}

export function getDb(): Database {
  return initializeDb();
}

export function addUser(nombre: string, email: string): User {
  const db = getDb();
  const id = Date.now().toString();
  const user: User = { id, nombre, email };
  db.users.push(user);
  return user;
}

export function getUsers(): User[] {
  const db = getDb();
  return db.users;
}

export function deleteUser(id: string): boolean {
  const db = getDb();
  const index = db.users.findIndex((user) => user.id === id);
  if (index !== -1) {
    db.users.splice(index, 1);
    return true;
  }
  return false;
}

