"use client";

import { useState, useEffect } from "react";

interface ShoppingItem {
  id: string;
  name: string;
  completed: boolean;
}

export default function ShoppingList() {
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchItems();
  }, []);

  const fetchItems = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/items");
      const data = await response.json();
      setItems(data);
    } catch (error) {
      console.error("Error fetching items:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAdd = async () => {
    if (input.trim() === "") return;

    try {
      const response = await fetch("/api/items", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: input }),
      });

      if (response.ok) {
        const newItem = await response.json();
        setItems([...items, newItem]);
        setInput("");
      }
    } catch (error) {
      console.error("Error adding item:", error);
    }
  };

  const handleToggleComplete = async (id: string, completed: boolean) => {
    try {
      const response = await fetch(`/api/items/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ completed: !completed }),
      });

      if (response.ok) {
        const updatedItem = await response.json();
        setItems(
          items.map((item) => (item.id === id ? updatedItem : item))
        );
      }
    } catch (error) {
      console.error("Error updating item:", error);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/items/${id}`, {
        method: "DELETE",
      });

      if (response.ok) {
        setItems(items.filter((item) => item.id !== id));
      }
    } catch (error) {
      console.error("Error deleting item:", error);
    }
  };

  const pendingCount = items.filter((item) => !item.completed).length;

  if (loading) {
    return <div className="text-center py-8">Cargando...</div>;
  }

  return (
    <div className="max-w-md mx-auto p-6 bg-white rounded-lg shadow">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">Mi Lista de Compras</h1>

      <div className="mb-6 p-4 bg-blue-100 rounded-lg">
        <p className="text-lg font-semibold text-blue-900">
          {pendingCount} por comprar
        </p>
      </div>

      <div className="flex gap-2 mb-6">
        <input
          type="text"
          placeholder="Producto"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={(e) => e.key === "Enter" && handleAdd()}
          className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button
          onClick={handleAdd}
          className="px-6 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition"
        >
          Agregar
        </button>
      </div>

      <div className="space-y-2">
        {items.length === 0 ? (
          <p className="text-gray-500 text-center py-8">
            No hay productos en la lista
          </p>
        ) : (
          items.map((item) => (
            <div
              key={item.id}
              className="flex items-center justify-between gap-3 p-4 bg-gray-50 rounded-lg border border-gray-200 hover:bg-gray-100 transition"
            >
              <div className="flex-1">
                <p
                  className={`text-base font-medium ${
                    item.completed
                      ? "text-gray-400 line-through"
                      : "text-gray-800"
                  }`}
                >
                  {item.completed && <span className="mr-2">✓</span>}
                  {item.name}
                </p>
              </div>

              <div className="flex gap-2">
                <button
                  onClick={() => handleToggleComplete(item.id, item.completed)}
                  className={`px-4 py-1 rounded font-medium text-sm transition ${
                    item.completed
                      ? "bg-gray-300 text-gray-700 hover:bg-gray-400"
                      : "bg-green-500 text-white hover:bg-green-600"
                  }`}
                >
                  {item.completed ? "No comprado" : "Comprado"}
                </button>

                <button
                  onClick={() => handleDelete(item.id)}
                  className="px-4 py-1 bg-red-500 text-white rounded font-medium text-sm hover:bg-red-600 transition"
                >
                  Borrar
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

