interface ShoppingItem {
  id: string;
  name: string;
  purchased: boolean;
}

interface Database {
  items: ShoppingItem[];
  nextId: number;
}

const db: Database = {
  items: [],
  nextId: 1,
};

declare global {
  var shoppingDb: Database;
}

if (!globalThis.shoppingDb) {
  globalThis.shoppingDb = db;
}

export function getDb(): Database {
  return globalThis.shoppingDb;
}

export function addItem(name: string): ShoppingItem {
  const db = getDb();
  const item: ShoppingItem = {
    id: String(db.nextId++),
    name,
    purchased: false,
  };
  db.items.push(item);
  return item;
}

export function toggleItemPurchased(id: string): ShoppingItem | null {
  const db = getDb();
  const item = db.items.find((i) => i.id === id);
  if (item) {
    item.purchased = !item.purchased;
  }
  return item || null;
}

export function deleteItem(id: string): boolean {
  const db = getDb();
  const index = db.items.findIndex((i) => i.id === id);
  if (index !== -1) {
    db.items.splice(index, 1);
    return true;
  }
  return false;
}

export function getAllItems(): ShoppingItem[] {
  const db = getDb();
  return [...db.items];
}

