interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

interface Database {
  authors: Author[];
  posts: Post[];
}

declare global {
  var db: Database;
}

if (!globalThis.db) {
  globalThis.db = {
    authors: [],
    posts: [],
  };
}

export function getAuthors(): Author[] {
  return globalThis.db.authors;
}

export function getPosts(): Post[] {
  return globalThis.db.posts;
}

export function createAuthor(name: string): Author {
  const id = Date.now().toString();
  const author: Author = { id, name };
  globalThis.db.authors.push(author);
  return author;
}

export function createPost(title: string, authorId: string): Post {
  const id = Date.now().toString();
  const post: Post = { id, title, authorId };
  globalThis.db.posts.push(post);
  return post;
}

export function deleteAuthor(authorId: string): boolean {
  const hasPost = globalThis.db.posts.some((p) => p.authorId === authorId);
  if (hasPost) {
    return false;
  }
  globalThis.db.authors = globalThis.db.authors.filter(
    (a) => a.id !== authorId
  );
  return true;
}

export function authorHasPosts(authorId: string): boolean {
  return globalThis.db.posts.some((p) => p.authorId === authorId);
}

