}

export async function POST(request: Request) {
  const { name } = await request.json();
  if (!name || typeof name !== "string") {
    return Response.json({ error: "Invalid name" }, { status: 400 });
  }
  const author = createAuthor(name.trim());
  return Response.json(author, { status: 201 });
}

export async function DELETE(request: Request) {
  const { id } = await request.json();
  if (!id) {
    return Response.json({ error: "Invalid id" }, { status: 400 });
  }

  const hasPosts = authorHasPosts(id);
  if (hasPosts) {
    return Response.json(
      { error: "El autor tiene posts" },
      { status: 400 }
    );
  }

  const success = deleteAuthor(id);
  if (!success) {
    return Response.json({ error: "Author not found" }, { status: 404 });
  }
  return Response.json({ success: true });
}

