  refresh: number;
}

export default function AuthorList({ refresh }: AuthorListProps) {
  const [authors, setAuthors] = useState<Author[]>([]);
  const [loading, setLoading] = useState(false);
  const [deleteError, setDeleteError] = useState<{ [key: string]: string }>({});

  useEffect(() => {
    fetchAuthors();
  }, [refresh]);

  async function fetchAuthors() {
    try {
      const res = await fetch("/api/authors");
      if (res.ok) {
        const data = await res.json();
        setAuthors(data);
      }
    } catch (error) {
      console.error("Error fetching authors:", error);
    }
  }

  async function handleDeleteAuthor(id: string) {
    setDeleteError({ ...deleteError, [id]: "" });
    try {
      const res = await fetch("/api/authors", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id }),
      });
      if (res.ok) {
        setAuthors(authors.filter((a) => a.id !== id));
        setDeleteError({ ...deleteError, [id]: "" });
      } else {
        const error = await res.json();
        setDeleteError({ ...deleteError, [id]: error.error });
      }
    } catch (error) {
      console.error("Error deleting author:", error);
    }
  }

  return (
    <div className="mb-8">
      <h2 className="text-xl font-bold mb-4">Autores</h2>
