import AuthorList from "@/components/AuthorList";
import PostForm from "@/components/PostForm";
import PostList from "@/components/PostList";

export default function Home() {
  const [authorRefresh, setAuthorRefresh] = useState(0);
  const [postRefresh, setPostRefresh] = useState(0);

  const handleAuthorCreated = () => {
    setAuthorRefresh((prev) => prev + 1);
  };

  const handlePostCreated = () => {
    setPostRefresh((prev) => prev + 1);
  };

  return (
    <main className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-6">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-3xl font-bold mb-8 text-gray-800">Blog</h1>

        <div className="bg-white rounded-lg shadow-md p-6 mb-8">
          <h2 className="text-2xl font-bold mb-4 text-gray-800">Crear autor</h2>
          <AuthorForm onAuthorCreated={handleAuthorCreated} />
          <AuthorList refresh={authorRefresh} />
        </div>

        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-bold mb-4 text-gray-800">Crear post</h2>
          <PostForm
