import db from '@/lib/db';

export async function DELETE(
  request: Request,
  { params }: { params: { id: string } }
) {
  const { id } = params;

  const authorIndex = db.authors.findIndex((a) => a.id === id);
  if (authorIndex === -1) {
    return Response.json({ error: 'Autor no encontrado' }, { status: 404 });
  }

  const hasPost = db.posts.some((p) => p.authorId === id);
  if (hasPost) {
    return Response.json(
      { error: 'El autor tiene posts' },
      { status: 400 }
    );
  }

  const deletedAuthor = db.authors.splice(authorIndex, 1);
  return Response.json(deletedAuthor[0]);
}

