'use client';

import { useEffect, useState } from 'react';

interface Author {
  id: string;
  name: string;
}

interface AuthorListProps {
  refreshTrigger: number;
}

export default function AuthorList({ refreshTrigger }: AuthorListProps) {
  const [authors, setAuthors] = useState<Author[]>([]);
  const [deleteErrors, setDeleteErrors] = useState<{ [key: string]: string }>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAuthors();
  }, [refreshTrigger]);

  const fetchAuthors = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/authors');
      const data = await res.json();
      setAuthors(data);
    } catch (error) {
      console.error('Error obteniendo autores:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const res = await fetch(`/api/authors/${id}`, {
        method: 'DELETE',
      });

      if (res.ok) {
        setDeleteErrors((prev) => {
          const newErrors = { ...prev };
          delete newErrors[id];
          return newErrors;
        });
        fetchAuthors();
      } else {
        const error = await res.json();
        setDeleteErrors((prev) => ({
          ...prev,
          [id]: error.error,
        }));
      }
    } catch (error) {
      console.error('Error borrando autor:', error);
    }
  };

  if (loading) {
    return <div className="text-gray-500">Cargando autores...</div>;
  }

  return (
    <div className="mb-8">
      <h2 className="text-2xl font-bold mb-4">Autores</h2>
      {authors.length === 0 ? (
        <p className="text-gray-500">No hay autores creados aún.</p>
      ) : (
        <ul className="space-y-2">
          {authors.map((author) => (
            <li
              key={author.id}
              className="flex items-center justify-between bg-gray-100 p-3 rounded-lg"
            >
              <span className="font-medium">{author.name}</span>
              <div className="flex flex-col items-end">
                {deleteErrors[author.id] && (
                  <span className="text-red-600 text-sm mb-1">
                    {deleteErrors[author.id]}
                  </span>
                )}
                <button
                  onClick={() => handleDelete(author.id)}
                  className="px-3 py-1 bg-red-500 text-white rounded text-sm hover:bg-red-600 transition"
                >
                  Borrar autor
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

