      />
      <select
        value={authorId}
        onChange={(e) => setAuthorId(e.target.value)}
        disabled={loading || authors.length === 0}
        className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
      >
        <option value="">Seleccionar autor</option>
        {authors.map((author) => (
          <option key={author.id} value={author.id}>
            {author.name}
          </option>
        ))}
      </select>
      <button
        type="submit"
        disabled={loading || authors.length === 0 || !authorId}
        className="px-6 py-2 bg-green-500 text-white rounded-lg font-medium hover:bg-green-600 disabled:bg-gray-400 transition"
      >
        Publicar
      </button>
    </form>
  );
}

