'use client';

import { useEffect, useState } from 'react';

interface Author {
  id: string;
  name: string;
}

interface Post {
  id: string;
  title: string;
  authorId: string;
}

interface PostListProps {
  refreshTrigger: number;
}

export default function PostList({ refreshTrigger }: PostListProps) {
  const [posts, setPosts] = useState<Post[]>([]);
  const [authors, setAuthors] = useState<{ [key: string]: string }>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, [refreshTrigger]);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [postsRes, authorsRes] = await Promise.all([
        fetch('/api/posts'),
        fetch('/api/authors'),
      ]);

      const postsData = await postsRes.json();
      const authorsData = await authorsRes.json();

      setPosts(postsData);

      const authorsMap: { [key: string]: string } = {};
      authorsData.forEach((author: Author) => {
        authorsMap[author.id] = author.name;
      });
      setAuthors(authorsMap);
    } catch (error) {
      console.error('Error obteniendo datos:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="text-gray-500">Cargando posts...</div>;
  }

  return (
    <div>
      <h2 className="text-2xl font-bold mb-4">Posts</h2>
      {posts.length === 0 ? (
        <p className="text-gray-500">No hay posts creados aún.</p>
      ) : (
        <ul className="space-y-3">
          {posts.map((post) => (
            <li
              key={post.id}
              className="bg-white border border-gray-200 p-4 rounded-lg shadow-sm"
            >
              <h3 className="font-semibold text-lg">{post.title}</h3>
              <p className="text-gray-600">
                por <span className="font-medium">{authors[post.authorId] || 'Desconocido'}</span>
              </p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

