interface Product {
  id: string;
  name: string;
  code: string;
  price: number;
}

interface DB {
  products: Product[];
}

declare global {
  var db: DB;
}

if (!globalThis.db) {
  globalThis.db = {
    products: [],
  };
}

export const db = globalThis.db;

export function addProduct(name: string, code: string, price: number): { success: boolean; error?: string } {
  // Validar nombre
  if (name.length < 3) {
    return { success: false, error: "Nombre muy corto" };
  }

  // Validar código duplicado
  if (db.products.some(p => p.code === code)) {
    return { success: false, error: "Código repetido" };
  }

  // Validar precio
  if (price < 0) {
    return { success: false, error: "Precio inválido" };
  }

  const id = Date.now().toString();
  db.products.push({
    id,
    name,
    code,
    price,
  });

  return { success: true };
}

export function getProducts(): Product[] {
  return db.products;
}

