        const data = await response.json();
        setProducts(data.products);
      } catch (error) {
        console.error('Error fetching products:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, [refreshTrigger]);

  if (loading) {
    return <div className="text-gray-500">Cargando productos...</div>;
  }

  if (products.length === 0) {
    return <div className="text-gray-500">No hay productos guardados.</div>;
  }

  return (
    <div className="space-y-2">
      {products.map((product) => (
        <div key={product.id} className="bg-gray-50 p-4 rounded border border-gray-200">
          <p className="font-semibold text-gray-800">{product.name}</p>
          <p className="text-sm text-gray-600">Código: {product.code}</p>
        </div>
      ))}
    </div>
  );
}

