'use client';

import { useState, useMemo } from 'react';

interface Empleado {
  nombre: string;
  edad: number;
}

const empleadosInicial: Empleado[] = [
  { nombre: 'Caro', edad: 35 },
  { nombre: 'Ana', edad: 30 },
  { nombre: 'Dani', edad: 28 },
  { nombre: 'Beto', edad: 25 },
];

export default function Page() {
  const [empleados, setEmpleados] = useState<Empleado[]>(empleadosInicial);
  const [filtro, setFiltro] = useState('');
  const [ordenPor, setOrdenPor] = useState<'nombre' | 'edad' | null>(null);

  const empleadosFiltrados = useMemo(() => {
    let resultado = [...empleados];

    if (filtro) {
      resultado = resultado.filter((e) =>
        e.nombre.toLowerCase().includes(filtro.toLowerCase())
      );
    }

    if (ordenPor === 'nombre') {
      resultado.sort((a, b) => a.nombre.localeCompare(b.nombre));
    } else if (ordenPor === 'edad') {
      resultado.sort((a, b) => a.edad - b.edad);
    }

    return resultado;
  }, [empleados, filtro, ordenPor]);

  const handleOrdenarNombre = () => {
    if (ordenPor === 'nombre') {
      setOrdenPor(null);
      setEmpleados(empleadosInicial);
    } else {
      setOrdenPor('nombre');
    }
  };

  const handleOrdenarEdad = () => {
    if (ordenPor === 'edad') {
      setOrdenPor(null);
      setEmpleados(empleadosInicial);
    } else {
      setOrdenPor('edad');
    }
  };

  return (
    <div className="p-8">
      <h1 className="text-2xl font-bold mb-6">Empleados</h1>

      <div className="flex gap-4 mb-6">
        <button
          onClick={handleOrdenarNombre}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition"
        >
          Ordenar por nombre
        </button>
        <button
          onClick={handleOrdenarEdad}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition"
        >
          Ordenar por edad
        </button>
      </div>

      <div className="mb-6">
        <input
          type="text"
          placeholder="Filtrar"
          value={filtro}
          onChange={(e) => setFiltro(e.target.value)}
          className="px-4 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500 w-full max-w-xs"
        />
      </div>

      <div className="overflow-x-auto mb-6">
        <table className="w-full border-collapse border border-gray-300">
          <thead>
            <tr className="bg-gray-100">
              <th className="border border-gray-300 px-4 py-2 text-left">
                Nombre
              </th>
              <th className="border border-gray-300 px-4 py-2 text-left">
                Edad
              </th>
            </tr>
          </thead>
          <tbody>
            {empleadosFiltrados.map((empleado) => (
              <tr key={empleado.nombre} className="hover:bg-gray-50">
                <td className="border border-gray-300 px-4 py-2">
                  {empleado.nombre}
                </td>
                <td className="border border-gray-300 px-4 py-2">
                  {empleado.edad}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="text-lg font-semibold">
        Empleados: {empleadosFiltrados.length}
      </div>
    </div>
  );
}

