import { useState, useMemo } from 'react';

interface Employee {
  name: string;
  age: number;
}

export default function EmployeesTable() {
  const initialEmployees: Employee[] = [
    { name: 'Caro', age: 35 },
    { name: 'Ana', age: 30 },
    { name: 'Dani', age: 28 },
    { name: 'Beto', age: 25 },
  ];

  const [employees, setEmployees] = useState(initialEmployees);
  const [filter, setFilter] = useState('');
  const [sortBy, setSortBy] = useState<'none' | 'name' | 'age'>('none');

  const filteredAndSorted = useMemo(() => {
    let result = [...employees];

    // Aplicar filtro
    if (filter) {
      result = result.filter((emp) =>
        emp.name.toLowerCase().includes(filter.toLowerCase())
      );
    }

    // Aplicar ordenamiento
    if (sortBy === 'name') {
      result.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortBy === 'age') {
      result.sort((a, b) => a.age - b.age);
    }

    return result;
  }, [employees, filter, sortBy]);

  const handleSortByName = () => {
    setSortBy(sortBy === 'name' ? 'none' : 'name');
  };

  const handleSortByAge = () => {
    setSortBy(sortBy === 'age' ? 'none' : 'age');
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-6">
      <div className="mb-6 flex flex-col gap-4">
        <input
          type="text"
          placeholder="Filtrar"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <div className="flex gap-3">
          <button
            onClick={handleSortByName}
            className={`px-4 py-2 rounded-lg font-semibold transition-colors ${
              sortBy === 'name'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-200 text-gray-800 hover:bg-gray-300'
            }`}
          >
            Ordenar por nombre
          </button>
          <button
            onClick={handleSortByAge}
            className={`px-4 py-2 rounded-lg font-semibold transition-colors ${
              sortBy === 'age'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-200 text-gray-800 hover:bg-gray-300'
            }`}
          >
            Ordenar por edad
          </button>
        </div>
      </div>

      <table className="w-full border-collapse mb-4">
        <thead>
          <tr className="bg-gray-100 border-b-2 border-gray-300">
            <th className="px-4 py-3 text-left font-semibold text-gray-800">Nombre</th>
            <th className="px-4 py-3 text-left font-semibold text-gray-800">Edad</th>
          </tr>
        </thead>
        <tbody>
          {filteredAndSorted.map((emp, index) => (
            <tr
              key={index}
              className="border-b border-gray-200 hover:bg-gray-50 transition-colors"
            >
              <td className="px-4 py-3 text-gray-800">{emp.name}</td>
              <td className="px-4 py-3 text-gray-800">{emp.age}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <div className="text-lg font-semibold text-gray-800">
        Empleados: {filteredAndSorted.length}
      </div>
    </div>
  );
}

