'use client';

import { useState, useEffect, useRef } from 'react';

export function Stopwatch() {
  const [time, setTime] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (isRunning) {
      intervalRef.current = setInterval(() => {
        setTime((prevTime) => prevTime + 1);
      }, 100);
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [isRunning]);

  const handleStart = () => {
    if (!isRunning) {
      setIsRunning(true);
    }
  };

  const handlePause = () => {
    setIsRunning(false);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTime(0);
  };

  return (
    <div className="bg-white rounded-lg shadow-2xl p-8 w-80">
      <div className="bg-gradient-to-r from-blue-500 to-purple-600 rounded-lg p-8 mb-8">
        <p className="text-white text-center text-4xl font-bold">
          Tiempo: {time}
        </p>
      </div>

      <div className="flex flex-col gap-4">
        <button
          onClick={handleStart}
          className="bg-green-500 hover:bg-green-600 text-white font-bold py-3 px-6 rounded-lg transition duration-200 active:scale-95"
        >
          Iniciar
        </button>

        <button
          onClick={handlePause}
          className="bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-6 rounded-lg transition duration-200 active:scale-95"
        >
          Pausar
        </button>

        <button
          onClick={handleReset}
          className="bg-red-500 hover:bg-red-600 text-white font-bold py-3 px-6 rounded-lg transition duration-200 active:scale-95"
        >
          Reiniciar
        </button>
      </div>
    </div>
  );
}

