'use client';

import { useState } from 'react';

export default function RegistrationForm() {
  const [step, setStep] = useState(1);
  const [name, setName] = useState('');
  const [plan, setPlan] = useState('Gratis');
  const [newsletter, setNewsletter] = useState(false);
  const [nameError, setNameError] = useState('');
  const [confirmed, setConfirmed] = useState(false);

  const handleNextFromStep1 = () => {
    if (!name.trim()) {
      setNameError('Nombre requerido');
      return;
    }
    setNameError('');
    setStep(2);
  };

  const handleBack = () => {
    setStep(step - 1);
  };

  const handleNextFromStep2 = () => {
    setStep(3);
  };

  const handleConfirm = () => {
    setConfirmed(true);
  };

  if (confirmed) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-100">
        <div className="bg-white p-8 rounded-lg shadow-lg text-center">
          <h1 className="text-3xl font-bold text-green-600">¡Listo, {name}!</h1>
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h2 className="text-2xl font-bold mb-6 text-center">
          Paso {step} de 3
        </h2>

        {step === 1 && (
          <div>
            <input
              type="text"
              placeholder="Nombre"
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                setNameError('');
              }}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg mb-2 focus:outline-none focus:border-blue-500"
            />
            {nameError && (
              <p className="text-red-500 text-sm mb-4">{nameError}</p>
            )}
            <button
              onClick={handleNextFromStep1}
              className="w-full bg-blue-500 text-white py-2 rounded-lg font-semibold hover:bg-blue-600 transition"
            >
              Siguiente
            </button>
          </div>
        )}

        {step === 2 && (
          <div>
            <div className="mb-6">
              <label className="block text-sm font-semibold mb-2">
                Plan
              </label>
              <select
                value={plan}
                onChange={(e) => setPlan(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500"
              >
                <option value="Gratis">Gratis</option>
                <option value="Pro">Pro</option>
              </select>
            </div>

            <div className="mb-6 flex items-center">
              <input
                type="checkbox"
                id="newsletter"
                checked={newsletter}
                onChange={(e) => setNewsletter(e.target.checked)}
                className="w-4 h-4 border border-gray-300 rounded focus:outline-none cursor-pointer"
              />
              <label
                htmlFor="newsletter"
                className="ml-3 text-sm font-semibold cursor-pointer"
              >
                Recibir novedades
              </label>
            </div>

            <div className="flex gap-3">
              <button
                onClick={handleBack}
                className="flex-1 bg-gray-300 text-gray-800 py-2 rounded-lg font-semibold hover:bg-gray-400 transition"
              >
                Atrás
              </button>
              <button
                onClick={handleNextFromStep2}
                className="flex-1 bg-blue-500 text-white py-2 rounded-lg font-semibold hover:bg-blue-600 transition"
              >
                Siguiente
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div>
            <div className="bg-gray-100 p-4 rounded-lg mb-6 text-center">
              <p className="mb-2">
                <strong>{name}</strong> eligió <strong>{plan}</strong>
              </p>
              {newsletter && (
                <p className="text-sm text-gray-600">Con novedades</p>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={handleBack}
                className="flex-1 bg-gray-300 text-gray-800 py-2 rounded-lg font-semibold hover:bg-gray-400 transition"
              >
                Atrás
              </button>
              <button
                onClick={handleConfirm}
                className="flex-1 bg-green-500 text-white py-2 rounded-lg font-semibold hover:bg-green-600 transition"
              >
                Confirmar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

