files.lib/db.ts:
interface Task {
  id: string;
  title: string;
  completed: boolean;
}

interface DB {
  tasks: Task[];
  nextId: number;
}

function getDB(): DB {
  if (!globalThis.db) {
    globalThis.db = {
      tasks: [],
      nextId: 1,
    };
  }
  return globalThis.db;
}

export function createTask(title: string): Task {
  const db = getDB();
  const task: Task = {
    id: String(db.nextId++),
    title,
    completed: false,
  };
  db.tasks.push(task);
  return task;
}

export function getTasks(): Task[] {
  const db = getDB();
  return db.tasks;
}

export function completeTask(id: string): Task | null {
  const db = getDB();
  const task = db.tasks.find((t) => t.id === id);
  if (task) {
    task.completed = true;
  }
  return task || null;
}

export function renameTask(id: string, newTitle: string): Task | null {
  const db = getDB();
  const task = db.tasks.find((t) => t.id === id);
  if (task) {
    task.title = newTitle;
  }
  return task || null;
}

