"use client";

import { useState } from "react";

interface Task {
  id: string;
  title: string;
  completed: boolean;
}

interface TaskItemProps {
  task: Task;
  onTaskUpdated: () => void;
}

export default function TaskItem({ task, onTaskUpdated }: TaskItemProps) {
  const [isRenaming, setIsRenaming] = useState(false);
  const [newTitle, setNewTitle] = useState(task.title);
  const [loading, setLoading] = useState(false);

  const handleComplete = async () => {
    setLoading(true);
    try {
      const res = await fetch(`/api/tasks/${task.id}/complete`, {
        method: "PATCH",
      });
      if (res.ok) {
        onTaskUpdated();
      }
    } catch (error) {
      console.error("Error completing task:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleRename = async () => {
    if (!newTitle.trim() || newTitle === task.title) {
      setIsRenaming(false);
      return;
    }

    setLoading(true);
    try {
      const res = await fetch(`/api/tasks/${task.id}/rename`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: newTitle }),
      });
      if (res.ok) {
        setIsRenaming(false);
        onTaskUpdated();
      }
    } catch (error) {
      console.error("Error renaming task:", error);
    } finally {
      setLoading(false);
    }
  };

  if (isRenaming) {
    return (
      <div className="flex gap-2 items-center p-3 bg-gray-50 border border-gray-200 rounded-md">
        <input
          type="text"
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
          placeholder="Nuevo título"
          disabled={loading}
          className="flex-1 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
          autoFocus
        />
        <button
          onClick={handleRename}
          disabled={loading}
          className="px-3 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 disabled:bg-gray-400 text-sm"
        >
          {loading ? "Guardando..." : "Guardar"}
        </button>
        <button
          onClick={() => {
            setIsRenaming(false);
            setNewTitle(task.title);
          }}
          disabled={loading}
          className="px-3 py-2 bg-gray-400 text-white rounded-md hover:bg-gray-500 disabled:bg-gray-400 text-sm"
        >
          Cancelar
        </button>
      </div>
    );
  }

  return (
    <div className="flex gap-2 items-center p-3 bg-white border border-gray-200 rounded-md">
      <span
        className={`flex-1 ${
          task.completed ? "line-through text-gray-500" : "text-gray-900"
        }`}
      >
        {task.title}
        {task.completed && " (hecha)"}
      </span>
      {!task.completed && (
        <button
          onClick={handleComplete}
          disabled={loading}
          className="px-3 py-1 bg-green-500 text-white rounded-md hover:bg-green-600 disabled:bg-gray-400 text-sm"
        >
          Hecha
        </button>
      )}
      {!task.completed && (
        <button
          onClick={() => setIsRenaming(true)}
          disabled={loading}
          className="px-3 py-1 bg-yellow-500 text-white rounded-md hover:bg-yellow-600 disabled:bg-gray-400 text-sm"
        >
          Renombrar
        </button>
      )}
    </div>
  );
}

