    const task: Task = {
      id: String(database.nextId++),
      title,
      completed: false,
    };
    database.tasks.push(task);
    return task;
  },

  markTaskAsCompleted: (id: string): Task | null => {
    const database = getDb();
    const task = database.tasks.find((t) => t.id === id);
    if (task) {
      task.completed = true;
    }
    return task || null;
  },

  updateTaskTitle: (id: string, newTitle: string): Task | null => {
    const database = getDb();
    const task = database.tasks.find((t) => t.id === id);
    if (task) {
      task.title = newTitle;
    }
    return task || null;
  },
};

