"use client";

import { useState, useEffect } from "react";
import TaskItem from "@/components/TaskItem";

interface Task {
  id: string;
  title: string;
  completed: boolean;
}

type FilterType = "all" | "pending" | "completed";

export default function TaskList() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [filter, setFilter] = useState<FilterType>("all");
  const [loading, setLoading] = useState(true);

  const fetchTasks = async () => {
    try {
      const response = await fetch("/api/tasks");
      const data = await response.json();
      setTasks(data);
    } catch (error) {
      console.error("Error fetching tasks:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTasks();
  }, []);

  const handleAddTask = async (title: string) => {
    if (!title.trim()) return;

    try {
      const response = await fetch("/api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title }),
      });

      if (response.ok) {
        const newTask = await response.json();
        setTasks([...tasks, newTask]);
      }
    } catch (error) {
      console.error("Error adding task:", error);
    }
  };

  const handleCompleteTask = async (id: string) => {
    try {
      const response = await fetch(`/api/tasks/${id}/complete`, {
        method: "PATCH",
      });

      if (response.ok) {
        const updatedTask = await response.json();
        setTasks(tasks.map((task) => (task.id === id ? updatedTask : task)));
      }
    } catch (error) {
      console.error("Error completing task:", error);
    }
  };

  const handleRenameTask = async (id: string, newTitle: string) => {
    if (!newTitle.trim()) return;

    try {
      const response = await fetch(`/api/tasks/${id}/rename`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title: newTitle }),
      });

      if (response.ok) {
        const updatedTask = await response.json();
        setTasks(tasks.map((task) => (task.id === id ? updatedTask : task)));
      }
    } catch (error) {
      console.error("Error renaming task:", error);
    }
  };

  const filteredTasks = tasks.filter((task) => {
    if (filter === "pending") return !task.completed;
    if (filter === "completed") return task.completed;
    return true;
  });

  return (
    <div className="w-full max-w-2xl mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6 text-gray-800">Gestor de Tareas</h1>

      <div className="mb-6 flex gap-2">
        <input
          type="text"
          placeholder="Tarea"
          id="taskInput"
          className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          onKeyPress={(e) => {
            if (e.key === "Enter") {
              const input = e.currentTarget as HTMLInputElement;
              handleAddTask(input.value);
              input.value = "";
            }
          }}
        />
        <button
          onClick={() => {
            const input = document.getElementById(
              "taskInput"
            ) as HTMLInputElement;
            handleAddTask(input.value);
            input.value = "";
          }}
          className="px-6 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors font-medium"
        >
          Agregar
        </button>
      </div>

      <div className="mb-6">
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as FilterType)}
          className="px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
          <option value="all">Todas</option>
          <option value="pending">Pendientes</option>
          <option value="completed">Hechas</option>
        </select>
      </div>

      {loading ? (
        <p className="text-gray-500 text-center">Cargando tareas...</p>
      ) : filteredTasks.length === 0 ? (
        <p className="text-gray-500 text-center">
          {filter === "all"
            ? "No hay tareas"
            : filter === "pending"
              ? "No hay tareas pendientes"
              : "No hay tareas completadas"}
        </p>
      ) : (
        <div className="space-y-2">
          {filteredTasks.map((task) => (
            <TaskItem
              key={task.id}
              task={task}
              onComplete={handleCompleteTask}
              onRename={handleRenameTask}
            />
          ))}
        </div>
      )}
    </div>
  );
}

