interface VotesData {
  dogs: number;
  cats: number;
}

declare global {
  var votes: VotesData;
}

if (!global.votes) {
  global.votes = {
    dogs: 0,
    cats: 0,
  };
}

export function getVotes(): VotesData {
  return global.votes;
}

export function addVote(option: 'dogs' | 'cats'): VotesData {
  global.votes[option]++;
  return global.votes;
}

export function resetVotes(): VotesData {
  global.votes = {
    dogs: 0,
    cats: 0,
  };
  return global.votes;
}

