import { getVotes, addVote, resetVotes } from '@/lib/db';

export async function GET() {
  const votes = getVotes();
  const total = votes.dogs + votes.cats;

  return Response.json({
    dogs: {
      votes: votes.dogs,
      percentage: total === 0 ? 0 : Math.round((votes.dogs / total) * 100),
    },
    cats: {
      votes: votes.cats,
      percentage: total === 0 ? 0 : Math.round((votes.cats / total) * 100),
    },
  });
}

export async function POST(request: Request) {
  const body = await request.json();
  const { option } = body;

  if (option !== 'dogs' && option !== 'cats') {
    return Response.json({ error: 'Invalid option' }, { status: 400 });
  }

  const votes = addVote(option);
  const total = votes.dogs + votes.cats;

  return Response.json({
    dogs: {
      votes: votes.dogs,
      percentage: total === 0 ? 0 : Math.round((votes.dogs / total) * 100),
    },
    cats: {
      votes: votes.cats,
      percentage: total === 0 ? 0 : Math.round((votes.cats / total) * 100),
    },
  });
}

export async function DELETE() {
  const votes = resetVotes();

  return Response.json({
    dogs: {
      votes: votes.dogs,
      percentage: 0,
    },
    cats: {
      votes: votes.cats,
      percentage: 0,
    },
  });
}

