  globalThis.voteData = {
    dogs: 0,
    cats: 0,
  };
}

export function calculatePercentages() {
  const data = globalThis.voteData!;
  const total = data.dogs + data.cats;

  if (total === 0) {
    return {
      dogsPercentage: 0,
      catsPercentage: 0,
      total: 0,
    };
  }

  return {
    dogsPercentage: Math.round((data.dogs / total) * 100),
    catsPercentage: Math.round((data.cats / total) * 100),
    total,
  };
}

