'use client';

import { useState, useEffect } from 'react';

interface Product {
  id: string;
  name: string;
}

interface CatalogData {
  products: Product[];
  total: number;
  page: number;
  pageSize: number;
}

export default function Catalog() {
  const [data, setData] = useState<CatalogData>({
    products: [],
    total: 0,
    page: 1,
    pageSize: 5,
  });
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchProducts = async (pageNum: number, searchTerm: string) => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page: pageNum.toString(),
        search: searchTerm,
      });
      const response = await fetch(`/api/products?${params}`);
      const result = await response.json();
      setData(result);
    } catch (error) {
      console.error('Error fetching products:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLoadExamples = async () => {
    try {
      await fetch('/api/products/load', { method: 'POST' });
      fetchProducts(1, '');
    } catch (error) {
      console.error('Error loading examples:', error);
    }
  };

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newSearch = e.target.value;
    setSearch(newSearch);
    fetchProducts(1, newSearch);
  };

  const handlePrevious = () => {
    if (data.page > 1) {
      fetchProducts(data.page - 1, search);
    }
  };

  const handleNext = () => {
    const maxPage = Math.ceil(data.total / data.pageSize);
    if (data.page < maxPage) {
      fetchProducts(data.page + 1, search);
    }
  };

  useEffect(() => {
    fetchProducts(1, '');
  }, []);

  const maxPage = Math.ceil(data.total / data.pageSize);
  const hasPrevious = data.page > 1;
  const hasNext = data.page < maxPage;

  return (
    <div className="max-w-2xl mx-auto p-6">
      <button
        onClick={handleLoadExamples}
        className="mb-6 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition"
      >
        Cargar ejemplos
      </button>

      <input
        type="text"
        placeholder="Buscar"
        value={search}
        onChange={handleSearch}
        className="w-full mb-6 px-4 py-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
      />

      <div className="mb-4 text-sm text-gray-600">
        Total: {data.total}
      </div>

      <div className="mb-6">
        {loading ? (
          <div className="text-center py-8 text-gray-500">Cargando...</div>
        ) : data.products.length > 0 ? (
          <ul className="space-y-2">
            {data.products.map((product) => (
              <li
                key={product.id}
                className="px-4 py-3 bg-white border border-gray-200 rounded hover:bg-gray-50"
              >
                {product.name}
              </li>
            ))}
          </ul>
        ) : (
          <div className="text-center py-8 text-gray-500">
            No hay productos
          </div>
        )}
      </div>

      <div className="flex gap-2 justify-center">
        <button
          onClick={handlePrevious}
          disabled={!hasPrevious}
          className="px-4 py-2 bg-gray-300 text-gray-800 rounded hover:bg-gray-400 disabled:opacity-50 disabled:cursor-not-allowed transition"
        >
          Anterior
        </button>
        <button
          onClick={handleNext}
          disabled={!hasNext}
          className="px-4 py-2 bg-gray-300 text-gray-800 rounded hover:bg-gray-400 disabled:opacity-50 disabled:cursor-not-allowed transition"
        >
          Siguiente
        </button>
      </div>
    </div>
  );
}

