files.lib/db.ts:
interface User {
  email: string;
  passwordHash: string;
}

interface Note {
  id: string;
  email: string;
  content: string;
  createdAt: number;
}

interface Database {
  users: Map<string, User>;
  notes: Map<string, Note>;
}

declare global {
  var db: Database;
}

function hashPassword(password: string): string {
  let hash = 0;
  for (let i = 0; i < password.length; i++) {
    const char = password.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(36);
}

function initDb(): Database {
  if (!globalThis.db) {
    globalThis.db = {
      users: new Map(),
      notes: new Map(),
    };
  }
  return globalThis.db;
}

export const db = initDb();

export function createUser(email: string, password: string): boolean {
  if (db.users.has(email)) {
    return false;
  }
  const passwordHash = hashPassword(password);
  db.users.set(email, { email, passwordHash });
  return true;
}

export function verifyUser(email: string, password: string): boolean {
  const user = db.users.get(email);
  if (!user) {
    return false;
  }
  const passwordHash = hashPassword(password);
  return user.passwordHash === passwordHash;
}

export function addNote(email: string, content: string): Note {
  const id = Date.now().toString();
  const note: Note = {
    id,
    email,
    content,
    createdAt: Date.now(),
  };
  db.notes.set(id, note);
  return note;
}

export function getNotesByEmail(email: string): Note[] {
  return Array.from(db.notes.values())
    .filter((note) => note.email === email)
    .sort((a, b) => b.createdAt - a.createdAt);
}

