"use client";

import { useState, useEffect } from "react";

interface Note {
  id: string;
  email: string;
  content: string;
  createdAt: number;
}

interface NotesProps {
  email: string;
  onLogout: () => void;
}

export default function Notes({ email, onLogout }: NotesProps) {
  const [notes, setNotes] = useState<Note[]>([]);
  const [noteContent, setNoteContent] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [isAdding, setIsAdding] = useState(false);

  useEffect(() => {
    fetchNotes();
  }, [email]);

  const fetchNotes = async () => {
    setIsLoading(true);
    try {
      const response = await fetch(`/api/notes?email=${encodeURIComponent(email)}`);
      const data = await response.json();
      setNotes(data);
    } catch (err) {
      console.error("Error al cargar notas:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddNote = async () => {
    if (!noteContent.trim()) {
      return;
    }

    setIsAdding(true);
    try {
      const response = await fetch("/api/notes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, content: noteContent }),
      });

      if (response.ok) {
        const newNote = await response.json();
        setNotes([newNote, ...notes]);
        setNoteContent("");
      }
    } catch (err) {
      console.error("Error al agregar nota:", err);
    } finally {
      setIsAdding(false);
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white p-8 rounded-lg shadow-md w-full max-w-2xl">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold text-gray-800">
            Hola, <span className="text-blue-500">{email}</span>
          </h1>
          <button
            onClick={onLogout}
            className="bg-red-500 text-white px-4 py-2 rounded-lg font-semibold hover:bg-red-600 transition"
          >
            Salir
          </button>
        </div>

        <div className="flex gap-2 mb-6">
          <input
            type="text"
            placeholder="Nota"
            value={noteContent}
            onChange={(e) => setNoteContent(e.target.value)}
            className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            disabled={isAdding}
            onKeyPress={(e) => {
              if (e.key === "Enter" && !isAdding) {
                handleAddNote();
              }
            }}
          />
          <button
            onClick={handleAddNote}
            disabled={isAdding || !noteContent.trim()}
            className="bg-blue-500 text-white px-6 py-2 rounded-lg font-semibold hover:bg-blue-600 disabled:bg-gray-400 transition"
          >
            {isAdding ? "..." : "Agregar"}
          </button>
        </div>

        <div className="space-y-3">
          {isLoading ? (
            <p className="text-gray-500 text-center">Cargando notas...</p>
          ) : notes.length === 0 ? (
            <p className="text-gray-500 text-center">No tienes notas aún</p>
          ) : (
            notes.map((note) => (
              <div
                key={note.id}
                className="p-4 bg-gray-50 border border-gray-200 rounded-lg"
              >
                <p className="text-gray-800">{note.content}</p>
                <p className="text-xs text-gray-500 mt-2">
                  {new Date(note.createdAt).toLocaleString()}
                </p>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

