export async function POST(request: Request) {
  const { email, password } = await request.json();

  if (!email || !password) {
    return Response.json(
      { error: "Email y contraseña requeridos" },
      { status: 400 }
    );
  }

  const success = createUser(email, password);

  if (!success) {
