import type { CartItem } from "@/lib/data";

export default function Summary({ cart, onClear }: { cart: CartItem[]; onClear: () => void }) {
  const total = cart.reduce((sum, i) => sum + i.product.price * i.qty, 0);
  const hasDiscount = total > 50;
  const discount = hasDiscount ? total * 0.1 : 0;
  const finalTotal = total - discount;

  return (
    <div className="flex flex-col gap-2 border-t pt-2">
      <div className="flex items-center justify-between">
        <span className="font-bold">Total: ${total.toFixed(2)}</span>
        <button className="danger" onClick={onClear}>Vaciar carrito</button>
      </div>
      {hasDiscount && (
        <div className="flex flex-col gap-1 text-sm">
          <span className="text-green-600">Descuento 10%: -${discount.toFixed(2)}</span>
          <span className="font-bold text-green-600">Total final: ${finalTotal.toFixed(2)}</span>
        </div>
      )}
    </div>
  );
}

