import { useState } from "react";
import type { Product } from "@/lib/data";
import SearchBox from "@/components/SearchBox";
import ProductCard from "@/components/ProductCard";

export default function Catalog({ products, onAdd }: { products: Product[]; onAdd: (p: Product) => void }) {
  const [query, setQuery] = useState("");
  const [sortByPrice, setSortByPrice] = useState(false);
  let shown = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));

  if (sortByPrice) {
    shown = [...shown].sort((a, b) => a.price - b.price);
  }

  return (
    <div className="flex flex-col gap-2">
      <div className="flex gap-2 items-center">
        <SearchBox value={query} onChange={setQuery} />
        <button
          onClick={() => setSortByPrice(!sortByPrice)}
          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 whitespace-nowrap"
        >
          {sortByPrice ? "✓ Ordenar por precio" : "Ordenar por precio"}
        </button>
      </div>
      <div className="grid grid-cols-3 gap-2">
        {shown.map((p) => (
          <ProductCard key={p.id} product={p} onAdd={() => onAdd(p)} />
        ))}
      </div>
      {shown.length === 0 && <span className="text-gray-500">Sin resultados</span>}
    </div>
  );
}

